import AppKit
import MandCore

/// Mac side of clipboard sharing (protocol §3a, `clipboard.v1`). Text only; never history.
@MainActor
public final class ClipboardService {
    public enum SendResult: Equatable {
        case sent, empty, concealed, tooLarge
    }

    /// Pasteboard types that password managers use to mark secrets (nspasteboard.org conventions).
    static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    ]
    static let fromPhoneType = NSPasteboard.PasteboardType("dev.mand.from-phone")

    private let pasteboard: NSPasteboard
    private var lastSeenChange: Int
    private var timer: Timer?

    public init(pasteboard: NSPasteboard = .general) {
        self.pasteboard = pasteboard
        lastSeenChange = pasteboard.changeCount
    }

    /// Reads the current clipboard text if it's safe to share.
    public func currentText() -> (String?, SendResult) {
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        if !types.isDisjoint(with: Self.sensitiveTypes) { return (nil, .concealed) }
        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return (nil, .empty) }
        guard text.utf8.count <= Message.maxClipboardBytes else { return (nil, .tooLarge) }
        return (text, .sent)
    }

    /// Puts text from the phone on the Mac clipboard.
    public func apply(_ text: String) {
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        pasteboard.setData(Data(), forType: Self.fromPhoneType)
        lastSeenChange = pasteboard.changeCount
    }

    /// Opt-in: calls `onCopy` with each new safe text the user copies on the Mac (checked once a second).
    public func watch(_ onCopy: @escaping @MainActor (String) -> Void) {
        stopWatching()
        lastSeenChange = pasteboard.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self, self.pasteboard.changeCount != self.lastSeenChange else { return }
                self.lastSeenChange = self.pasteboard.changeCount
                let types = Set((self.pasteboard.types ?? []).map(\.rawValue))
                guard !types.contains(Self.fromPhoneType.rawValue) else { return } // don't echo phone text back
                let (text, result) = self.currentText()
                if result == .sent, let text { onCopy(text) }
            }
        }
    }

    public func stopWatching() {
        timer?.invalidate()
        timer = nil
    }
}
